    f(fix_fields[13], self.maturity_date);
    f(fix_fields[14], self.maturity_time);
    f(fix_fields[15], self.maturity_frequency_unit);
    f(fix_fields[16], self.maturity_frequency_period);
    f(fix_fields[17], self.settle_on_open_flag);
    f(fix_fields[18], self.instrmt_assignment_method);
    f(fix_fields[19], self.security_status);
    f(fix_fields[20], self.coupon_payment_date);
    f(fix_fields[21], self.restructuring_type);
    f(fix_fields[22], self.seniority);
    f(fix_fields[23], self.notional_percentage_outstanding);
    f(fix_fields[24], self.original_notional_percentage_outstanding);
    f(fix_fields[25], self.attachment_point);
    f(fix_fields[26], self.detachment_point);
    f(fix_fields[27], self.obligation_type);
    f(fix_fields[28], self.asset_group);
    f(fix_fields[29], self.asset_class);
    f(fix_fields[30], self.asset_sub_class);
    f(fix_fields[31], self.asset_type);
    f(fix_fields[32], self.asset_sub_type);
    f(fix_fields[33], self.secondary_asset_grp);
    f(fix_fields[34], self.asset_attribute_grp);
