    f(fix_fields[44], self.coupon_frequency_unit);
    f(fix_fields[45], self.coupon_day_count);
    f(fix_fields[46], self.coupon_other_day_count);
    f(fix_fields[47], self.convertible_bond_equity_id);
    f(fix_fields[48], self.convertible_bond_equity_id_source);
