    f(fix_fields[46], self.original_notional_percentage_outstanding);
    f(fix_fields[47], self.attachment_point);
    f(fix_fields[48], self.detachment_point);
    f(fix_fields[49], self.obligation_type);
    f(fix_fields[50], self.asset_group);
